{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Propafenone had a mean absolute oral bioavailability of 13% after a 150 mg therapeutic dose, below the 20% threshold, supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "DX-9065a showed a human absolute oral bioavailability of only 2–3%, well below the 20% threshold, supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lercanidipine was reported with an absolute oral bioavailability of about 30% after a single 10 mg oral dose, which would support high bioavailability, but this is contradicted by fed-condition records of about 10%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred absolute oral bioavailability measurements are below 20% (e.g., 13%, 2–3%, 18%), while the only above-threshold report is conflicted by fed-condition values of about 10%; therefore low bioavailability is better supported.",
  "evidence_gaps": [
    "Conflicting fed versus non-fed absolute bioavailability reports for lercanidipine create uncertainty about the single positive above-threshold value.",
    "Several records are qualitative (e.g., 'poor' or 'very low') without numeric threshold-relevant bioavailability values and were not used as affirmative low evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

